use std::fs

trait Shape {
    fn name(self) -> string
    fn corners(self) -> int
    fn double_area(self) -> int
}

struct Square { n: string, s: int }
struct Rect { n: string, w: int, h: int }
struct Rtri { n: string, a: int, b: int }
struct Trap { n: string, a: int, b: int, h: int }

impl Shape for Square {
    fn name(self) -> string { self.n }
    fn corners(self) -> int { 4 }
    fn double_area(self) -> int { 2 * self.s * self.s }
}

impl Shape for Rect {
    fn name(self) -> string { self.n }
    fn corners(self) -> int { 4 }
    fn double_area(self) -> int { 2 * self.w * self.h }
}

impl Shape for Rtri {
    fn name(self) -> string { self.n }
    fn corners(self) -> int { 3 }
    fn double_area(self) -> int { self.a * self.b }
}

impl Shape for Trap {
    fn name(self) -> string { self.n }
    fn corners(self) -> int { 4 }
    fn double_area(self) -> int { (self.a + self.b) * self.h }
}

fn num(parts: Vec<string>, i: int) -> int {
    let idx = i as usize
    if idx < parts.len() {
        parts[idx].parse::<int>().unwrap_or(0)
    } else {
        0
    }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut total = 0
    let mut best = -1
    let mut best_name = "none"
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            continue
        }
        let k = parts[0]
        let mut nm = ""
        let mut c = 0
        let mut d = 0
        if k == "square" {
            let s = Square { n: k, s: num(parts, 1) }
            nm = s.name()
            c = s.corners()
            d = s.double_area()
        } else if k == "rect" {
            let s = Rect { n: k, w: num(parts, 1), h: num(parts, 2) }
            nm = s.name()
            c = s.corners()
            d = s.double_area()
        } else if k == "rtri" {
            let s = Rtri { n: k, a: num(parts, 1), b: num(parts, 2) }
            nm = s.name()
            c = s.corners()
            d = s.double_area()
        } else if k == "trap" {
            let s = Trap { n: k, a: num(parts, 1), b: num(parts, 2), h: num(parts, 3) }
            nm = s.name()
            c = s.corners()
            d = s.double_area()
        } else {
            continue
        }
        println("${nm} corners=${c} area2=${d}")
        total += d
        if d > best {
            best = d
            best_name = nm
        }
    }
    println("total area2=${total}")
    if best < 0 {
        println("largest=none")
    } else {
        println("largest=${best_name} area2=${best}")
    }
}

